mapper.select:
SELECT
    CASE
        WHEN EXISTS (
            SELECT 1
            FROM account a
            WHERE a.user_id = #{userId}
        )
        OR EXISTS (
            SELECT 1
            FROM card cd
            WHERE cd.user_id = #{userId}
        )
        OR EXISTS (
            SELECT 1
            FROM `user` u
            WHERE u.id = #{userId}
              AND NULLIF(TRIM(u.connected_id), '') IS NOT NULL
        ) THEN TRUE
        ELSE FALSE
    END

SELECT
    COALESCE((
        SELECT SUM(sm.expected_saving)
        FROM saving_missions sm
        WHERE sm.user_id = #{userId}
          AND YEAR(sm.created_at) = #{year}
          AND MONTH(sm.created_at) = #{month}
          AND sm.status = '도전중'
    ), 0) AS total_expected_saving_amount,
    (
        SELECT COUNT(sm.id)
        FROM saving_missions sm
        WHERE sm.user_id = #{userId}
          AND YEAR(sm.created_at) = #{year}
          AND MONTH(sm.created_at) = #{month}
          AND sm.status = '도전중'
    ) AS in_progress_mission_count,
    (
        SELECT COUNT(sm.id)
        FROM saving_missions sm
        WHERE sm.user_id = #{userId}
          AND YEAR(sm.created_at) = #{year}
          AND MONTH(sm.created_at) = #{month}
          AND sm.status = '완료'
    ) AS completed_mission_count,
    representative.id AS mission_id,
    representative.category AS category_code,
    representative.title AS title,
    representative.status AS status,
    representative.expected_saving AS expected_saving_amount
FROM (
    SELECT 1 AS summary_base
) base
LEFT JOIN saving_missions representative
    ON representative.id = (
        SELECT sm.id
        FROM saving_missions sm
        WHERE sm.user_id = #{userId}
          AND YEAR(sm.created_at) = #{year}
          AND MONTH(sm.created_at) = #{month}
          AND sm.status = '도전중'
        ORDER BY
            sm.created_at DESC,
            sm.id DESC
        LIMIT 1
    )
